184	// Streaming parser for the strict single-block PEM structure used by key-id:
185	//
186	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
187	//   (base64 lines; no blank or whitespace-only lines) ...
188	//   -----END PUBLIC KEY-----
189	//   [ASCII ws]
190	//
191	// The BEGIN line must end in LF or CRLF, but the END marker needs no line
192	// terminator at all: once it is fully matched, EOF may follow immediately or
193	// any number of ASCII whitespace bytes -- the conventional trailing LF or
194	// CRLF included, but also spaces or tabs glued directly to the marker, with
195	// no requirement that the first such byte be a line feed.
196	//
197	// Bytes are fed straight from the read passes, chunk by chunk, and nothing is
198	// retained besides the fixed-size parser state and the decoded payload: the
199	// surrounding whitespace is merely classified and discarded, and each base64
200	// quantum is decoded the moment its fourth character arrives, so no base64
201	// text is ever accumulated. Memory use therefore depends on the size of the
202	// encoded public key itself, not on the amount of whitespace around the block
203	// or on the file size; no file-size limit is imposed.
204	//
205	// Anything outside the grammar above fails deterministically: non-whitespace
206	// outside the block, more than one block, any other PEM label (private keys,
207	// certificates, PKCS#1 RSA public keys, ...), malformed or truncated base64.
208	// finish() additionally verifies that the decoded payload is one complete,
209	// canonical DER SubjectPublicKeyInfo understood by the crypto library, so
210	// non-DER BER encodings and trailing bytes are rejected as well.
211	class PublicKeyPemSink {
212	public:
213	    explicit PublicKeyPemSink(const char* pathArg) : pathArg_(pathArg) {}
214	
215	    bool start() { return true; }
216	
217	    bool consume(const char* data, size_t size) {
218	        if (failed_) {
219	            return false;  // stay failed across the rest of the file
220	        }
221	        for (size_t i = 0; i < size; ++i) {
222	            if (!feed(static_cast<unsigned char>(data[i]))) {
223	                failed_ = true;
224	                reportInvalid();
225	                return false;
226	            }
227	        }
228	        return true;
229	    }
230	
231	    bool finish() {
232	        if (failed_) {
233	            return false;  // consume() already reported the reason
234	        }
235	        bool ok = false;
236	        switch (phase_) {
237	            case Phase::kEndMarker:
238	                // A fully matched END marker needs no trailing whitespace or
239	                // line feed at EOF; an unfinished match is a truncated marker.
240	                ok = markerMatched_ == kPemEnd.size();
241	                break;
242	            case Phase::kPostamble:
243	                // Complete marker already followed by at least one whitespace
244	                // byte; everything remaining was whitespace as well.
245	                ok = true;
246	                break;
247	            case Phase::kPreamble:       // empty or whitespace-only file
248	            case Phase::kBeginMarker:    // truncated BEGIN line
249	            case Phase::kBeginCr:        // CR in the header not followed by LF
250	            case Phase::kBodyLineStart:
251	            case Phase::kBodyData:
252	            case Phase::kBodyCr:         // truncated: no END line
253	                break;
254	        }
255	        if (ok) {
256	            ok = flushQuantumAtEnd() && validateSpkiDer();
257	        }
258	        if (!ok) {
259	            failed_ = true;
260	            reportInvalid();
261	        }
262	        return ok;
263	    }
264	
265	    // Valid only after finish() succeeded: the canonical SPKI DER.
266	    const std::vector<unsigned char>& spkiDer() const { return der_; }
267	
268	private:
269	    enum class Phase {
270	        kPreamble,
271	        kBeginMarker,
272	        kBeginCr,
273	        kBodyLineStart,
274	        kBodyData,
275	        kBodyCr,
276	        kEndMarker,
277	        kPostamble,
278	    };
279	
280	    bool feed(unsigned char c) {
281	        switch (phase_) {
282	            case Phase::kPreamble:
283	                if (isAsciiSpace(c)) {
284	                    return true;
285	                }
286	                if (c == static_cast<unsigned char>(kPemBegin[0])) {
287	                    markerMatched_ = 1;
288	                    phase_ = Phase::kBeginMarker;
289	                    return true;
290	                }
291	                return false;
292	
293	            case Phase::kBeginMarker:
294	                if (c == '\n') {
295	                    return markerMatched_ == kPemBegin.size() &&
296	                           beginComplete();
297	                }
298	                if (c == '\r') {
299	                    if (markerMatched_ != kPemBegin.size()) {
300	                        return false;
301	                    }
302	                    phase_ = Phase::kBeginCr;
303	                    return true;
304	                }
305	                if (markerMatched_ < kPemBegin.size() &&
306	                    c == static_cast<unsigned char>(kPemBegin[markerMatched_])) {
307	                    ++markerMatched_;
308	                    return true;
309	                }
310	                return false;
311	
312	            case Phase::kBeginCr:
313	                // A CR in the header is only legal as the CR of CRLF.
314	                return c == '\n' && beginComplete();
315	
316	            case Phase::kBodyLineStart:
317	                if (c == '-') {
318	                    markerMatched_ = 1;
319	                    phase_ = Phase::kEndMarker;
320	                    return true;
321	                }
322	                if (c == '\n') {
323	                    return false;  // no blank lines inside the block
324	                }
325	                if (isAsciiSpace(c)) {
326	                    return false;  // whitespace is allowed only around it
327	                }
328	                return feedBase64Data(c);
329	
330	            case Phase::kBodyData:
331	                if (c == '\n') {
332	                    if (lineEmpty_) {
333	                        return false;  // blank or whitespace-only line
334	                    }
335	                    lineEmpty_ = true;
336	                    phase_ = Phase::kBodyLineStart;
337	                    return true;
338	                }
339	                if (c == '\r') {
340	                    if (lineEmpty_) {
341	                        return false;
342	                    }
343	                    phase_ = Phase::kBodyCr;
344	                    return true;
345	                }
346	                if (isAsciiSpace(c)) {
347	                    return false;
348	                }
349	                return feedBase64Data(c);
350	
351	            case Phase::kBodyCr:
352	                // Bare CRs are not line separators: a CR must end with LF.
353	                if (c != '\n') {
354	                    return false;
355	                }
356	                lineEmpty_ = true;
357	                phase_ = Phase::kBodyLineStart;
358	                return true;
359	
360	            case Phase::kEndMarker:
361	                // While the marker is still incomplete its bytes must match
362	                // literally. A complete marker terminates the block outright:
363	                // LF/CRLF, spaces and tabs are all just postamble whitespace,
364	                // so the byte right after the final '-' need not be a line
365	                // feed. Whitespace inside a still-unfinished marker is not
366	                // part of the literal and fails like any other mismatch.
367	                if (markerMatched_ == kPemEnd.size()) {
368	                    if (isAsciiSpace(c)) {
369	                        return endComplete();
370	                    }
371	                    return false;
372	                }
373	                if (c == static_cast<unsigned char>(
374	                        kPemEnd[markerMatched_])) {
375	                    ++markerMatched_;
376	                    return true;
377	                }
378	                return false;
379	
380	            case Phase::kPostamble:
381	                // Everything still in the file must be ASCII whitespace; a
382	                // second block or any appended text is rejected, not ignored.
383	                return isAsciiSpace(c);
384	        }
385	        return false;
386	    }
387	
388	    bool beginComplete() {
389	        phase_ = Phase::kBodyLineStart;
390	        lineEmpty_ = true;
391	        return true;
392	    }
393	
394	    bool endComplete() {
395	        phase_ = Phase::kPostamble;
396	        return true;
397	    }
398	
399	    static int base64Value(unsigned char c) {
400	        if (c >= 'A' && c <= 'Z') return c - 'A';
401	        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
402	        if (c >= '0' && c <= '9') return c - '0' + 52;
403	        if (c == '+') return 62;
404	        if (c == '/') return 63;
405	        return -1;
406	    }
407	
408	    // Feeds one character of a payload line. '-' is deliberately outside the
409	    // alphabet (it starts the END marker, handled by the caller), so any other
410	    // PEM boundary fails here rather than being consumed. Decoding is strict
411	    // and canonical, quantum by quantum; padding is legal only as the
412	    // conventional "x=" / "xx==" tail of the stream, and its unused bits must
413	    // be zero. This mirrors the former whole-file decoder exactly.
414	    bool feedBase64Data(unsigned char c) {
415	        phase_ = Phase::kBodyData;
416	        lineEmpty_ = false;
417	
418	        quantum_[quantumLen_++] = c;
419	        if (quantumLen_ < 4) {
420	            return true;  // wait for the rest of the quantum
421	        }
422	        quantumLen_ = 0;
423	
424	        const int a = base64Value(quantum_[0]);
425	        const int b = base64Value(quantum_[1]);
426	        if (a < 0 || b < 0) {
427	            return false;
428	        }
429	
430	        const bool pad2 = quantum_[2] == '=';
431	        const bool pad3 = quantum_[3] == '=';
432	        if (sawPadding_) {
433	            return false;  // no complete quantum may follow a padded one
434	        }
435	
436	        if (pad2) {
437	            if (!pad3) {
438	                return false;  // '=' at position 2 requires one at position 3
439	            }
440	            if ((b & 0x0f) != 0) {
441	                return false;  // non-canonical: unused padding bits must be 0
442	            }
443	            der_.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
444	            sawPadding_ = true;
445	        } else {
446	            const int cv = base64Value(quantum_[2]);
447	            if (cv < 0) {
448	                return false;
449	            }
450	            if (pad3) {
451	                if ((cv & 0x03) != 0) {
452	                    return false;  // non-canonical: unused padding bits must be 0
453	                }
454	                der_.push_back(
455	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
456	                der_.push_back(static_cast<unsigned char>(
457	                    ((b & 0x0f) << 4) | (cv >> 2)));
458	                sawPadding_ = true;
459	            } else {
460	                const int d = base64Value(quantum_[3]);
461	                if (d < 0) {
462	                    return false;
463	                }
464	                der_.push_back(
465	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
466	                der_.push_back(static_cast<unsigned char>(
467	                    ((b & 0x0f) << 4) | (cv >> 2)));
468	                der_.push_back(static_cast<unsigned char>(
469	                    ((cv & 0x03) << 6) | d));
470	            }
471	        }
472	        return true;
473	    }
474	
475	    // At EOF the payload must have ended on a quantum boundary and must
476	    // decode to at least one byte.
477	    bool flushQuantumAtEnd() {
478	        if (quantumLen_ != 0 || der_.empty()) {
479	            return false;
480	        }
481	        return true;
482	    }
483	
484	    // Validates that the decoded payload is one complete SubjectPublicKeyInfo
485	    // DER structure covering every byte, understood by the crypto library, and
486	    // in canonical encoding. Re-encoding the parsed structure must reproduce
487	    // the payload byte for byte; that round trip rules out non-DER BER
488	    // encodings and other representations OpenSSL might otherwise accept. The
489	    // bytes hashed for the fingerprint are therefore the canonical SPKI DER,
490	    // so PEM line wrapping and line endings never influence the result.
491	    bool validateSpkiDer() {
492	        const unsigned char* p = der_.data();
493	        const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
494	            d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(der_.size()), nullptr,
495	                          nullptr),
496	            &EVP_PKEY_free);
497	        if (!pkey) {
498	            return false;
499	        }
500	        if (p - der_.data() != static_cast<ptrdiff_t>(der_.size())) {
501	            return false;  // trailing bytes after the SPKI structure
502	        }
503	
504	        const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
505	        if (encLen <= 0 || static_cast<size_t>(encLen) != der_.size()) {
506	            return false;
507	        }
508	        std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
509	        unsigned char* q = reencoded.data();
510	        if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != der_) {
511	            return false;  // non-canonical DER
512	        }
513	        return true;
514	    }
515	
516	    void reportInvalid() const {
517	        std::cerr << "sealmark: '" << pathArg_
518	                  << "' does not contain a single valid PEM-encoded "
519	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
520	    }
521	
522	    Phase phase_ = Phase::kPreamble;
523	    size_t markerMatched_ = 0;  // prefix length of the marker being matched
524	    bool lineEmpty_ = true;     // current body line has seen no data yet
525	    unsigned char quantum_[4] = {};
526	    size_t quantumLen_ = 0;
527	    bool sawPadding_ = false;  // a padded (final) quantum already occurred
528	    bool failed_ = false;
529	    const char* pathArg_ = nullptr;
530	    std::vector<unsigned char> der_;
531	};
