533	// Renders bytes as lowercase hexadecimal with no separators or prefix.
534	std::string toHexLower(const unsigned char* data, size_t size) {
535	    static constexpr char kHex[] = "0123456789abcdef";
536	    std::string out;
537	    out.reserve(2 * size);
538	    for (size_t i = 0; i < size; ++i) {
539	        out.push_back(kHex[data[i] >> 4]);
540	        out.push_back(kHex[data[i] & 0x0f]);
541	    }
542	    return out;
543	}
544	
545	int digestFile(const char* pathArg) {
546	    Sha256StreamSink sink(pathArg);
547	    if (!processFileChunks(pathArg, sink)) {
548	        return 1;
549	    }
550	
551	    std::cout << kDigestPrefix
552	              << toHexLower(sink.hash(), kSha256Size) << '\n';
553	    return 0;
554	}
555	
556	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
557	// characters: no missing prefix, no uppercase, no other algorithm names,
558	// no surrounding whitespace or trailing content.
559	bool isValidExpectedDigest(std::string_view digest) {
560	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
561	        return false;
562	    }
563	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
564	        return false;
565	    }
566	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
567	        const char c = digest[i];
568	        const bool isHex =
569	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
570	        if (!isHex) {
571	            return false;
572	        }
573	    }
574	    return true;
575	}
576	
577	int verifyDigestFile(const char* pathArg, std::string_view expected) {
578	    Sha256StreamSink sink(pathArg);
579	    if (!processFileChunks(pathArg, sink)) {
580	        return 1;
581	    }
582	
583	    std::string actual;
584	    actual.reserve(kDigestPrefix.size() + kDigestHexLen);
585	    actual.append(kDigestPrefix);
586	    actual.append(toHexLower(sink.hash(), kSha256Size));
587	
588	    if (actual == expected) {
589	        std::cout << "match\n";
590	        return 0;
591	    }
592	    std::cout << "mismatch\n";
593	    return 3;
594	}
595	
596	int keyIdFile(const char* pathArg) {
597	    PublicKeyPemSink sink(pathArg);
598	    if (!processFileChunks(pathArg, sink)) {
599	        return 1;
600	    }
601	
602	    const std::vector<unsigned char>& spkiDer = sink.spkiDer();
603	    unsigned char hash[kSha256Size];
604	    unsigned int hashLen = 0;
605	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
606	                   EVP_sha256(), nullptr) != 1 ||
607	        hashLen != kSha256Size) {
608	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
609	                  << "'\n";
610	        return 1;
611	    }
612	
613	    std::cout << kSpkiFingerprintPrefix
614	              << toHexLower(hash, kSha256Size) << '\n';
615	    return 0;
616	}
