620	int main(int argc, char* argv[]) {
621	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
622	        std::cout << "sealmark 0.1.0\n";
623	        return 0;
624	    }
625	    if (argc == 3 && std::string_view(argv[1]) == "digest") {
